-- api_name is the key in custom jsonb, the API body and every saved filter, so it never changes (ADR-0006).
CREATE FUNCTION api_name_immutable() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF NEW.api_name IS DISTINCT FROM OLD.api_name THEN
    RAISE EXCEPTION '%: api_name is immutable', TG_TABLE_NAME USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END $$;--> statement-breakpoint
CREATE TRIGGER modules_api_name_immutable BEFORE UPDATE OF api_name ON modules FOR EACH ROW EXECUTE FUNCTION api_name_immutable();--> statement-breakpoint
CREATE TRIGGER fields_api_name_immutable BEFORE UPDATE OF api_name ON fields FOR EACH ROW EXECUTE FUNCTION api_name_immutable();--> statement-breakpoint

-- Every member reads metadata (forms render from it); only an admin writes it (SCHEMA § RLS, admin_only).
-- No DELETE except layout parts: modules, fields and picklist values are deactivated, never removed.
GRANT SELECT, INSERT, UPDATE ON modules, fields, picklists, picklist_values, layouts, layout_sections, layout_fields, field_permissions TO crm_app;--> statement-breakpoint
GRANT DELETE ON layout_sections, layout_fields TO crm_app;--> statement-breakpoint
DO $$
DECLARE t text;
BEGIN
  FOREACH t IN ARRAY ARRAY['modules', 'fields', 'picklists', 'picklist_values', 'layouts', 'layout_sections', 'layout_fields', 'field_permissions'] LOOP
    EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY', t);
    EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY', t);
    EXECUTE format('CREATE POLICY tenant_isolation ON %I TO crm_app USING (org_id = app.org_id()) WITH CHECK (org_id = app.org_id())', t);
    EXECUTE format($p$CREATE POLICY admin_only_insert ON %I AS RESTRICTIVE FOR INSERT TO crm_app WITH CHECK (current_setting('app.role', true) = 'admin')$p$, t);
    EXECUTE format($p$CREATE POLICY admin_only_update ON %I AS RESTRICTIVE FOR UPDATE TO crm_app USING (current_setting('app.role', true) = 'admin')$p$, t);
    EXECUTE format($p$CREATE POLICY admin_only_delete ON %I AS RESTRICTIVE FOR DELETE TO crm_app USING (current_setting('app.role', true) = 'admin')$p$, t);
  END LOOP;
END $$;
